Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "calculate": "isValid(datum[''Custo acumulado combustão'']) && isValid(datum[''Custo acumulado elétrico'']) ? (datum[''Custo acumulado combustão''] >= datum[''Custo acumulado elétrico''] ? format(datum[''Custo acumulado combustão''] - datum[''Custo acumulado elétrico''], ''$,.0f'') + '' a favor do '' + datum[''Rótulo elétrico''] : format(datum[''Custo acumulado elétrico''] - datum[''Custo acumulado combustão''], ''$,.0f'') + '' a favor do '' + datum[''Rótulo combustão'']) : ''—''",
      "as": "Saldo no ano"
    },
    {
      "calculate": "format(datum[''Custo acumulado combustão''], ''$,.0f'')",
      "as": "tt_c"
    },
    {
      "calculate": "format(datum[''Custo acumulado elétrico''], ''$,.0f'')",
      "as": "tt_e"
    },
    {
      "calculate": "isValid(datum[''Custo acumulado combustão'']) || isValid(datum[''Custo acumulado elétrico'']) ? datum[''Ano de uso''] : null",
      "as": "_a_ok"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "_a_ok",
          "as": "amax"
        }
      ]
    }
  ],
  "layer": [
    {
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "k"
            }
          ]
        },
        {
          "filter": "datum.k == 1"
        },
        {
          "filter": "isValid(datum[''Anos para pagar'']) && datum[''Anos para pagar''] > 0 && datum[''Anos para pagar''] <= datum.amax"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "rule",
            "color": "#F2C811",
            "strokeWidth": 2
          },
          "encoding": {
            "x": {
              "field": "Anos para pagar",
              "type": "quantitative"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "(datum[''Anos para pagar''] <= 0.6 * datum.amax)"
            }
          ],
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "dx": 6,
            "fontSize": 11,
            "fontWeight": "bold",
            "color": "#967100"
          },
          "encoding": {
            "x": {
              "field": "Anos para pagar",
              "type": "quantitative"
            },
            "y": {
              "value": 4
            },
            "text": {
              "value": "empata aqui"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "!(datum[''Anos para pagar''] <= 0.6 * datum.amax)"
            }
          ],
          "mark": {
            "type": "text",
            "align": "right",
            "baseline": "top",
            "dx": -6,
            "fontSize": 11,
            "fontWeight": "bold",
            "color": "#967100"
          },
          "encoding": {
            "x": {
              "field": "Anos para pagar",
              "type": "quantitative"
            },
            "y": {
              "value": 4
            },
            "text": {
              "value": "empata aqui"
            }
          }
        }
      ]
    },
    {
      "transform": [
        {
          "fold": [
            "Custo acumulado combustão",
            "Custo acumulado elétrico"
          ],
          "as": [
            "serie",
            "valor"
          ]
        },
        {
          "filter": "isValid(datum.valor)"
        },
        {
          "calculate": "datum.serie == ''Custo acumulado combustão'' ? datum[''Rótulo combustão''] : datum[''Rótulo elétrico'']",
          "as": "Carro"
        },
        {
          "calculate": "datum.serie == ''Custo acumulado combustão'' ? 1 : 2",
          "as": "tipo"
        }
      ],
      "mark": {
        "type": "line",
        "strokeWidth": 3,
        "point": {
          "filled": true,
          "size": 40
        }
      },
      "encoding": {
        "x": {
          "field": "Ano de uso",
          "type": "quantitative",
          "title": "Anos de uso",
          "axis": {
            "tickMinStep": 1,
            "format": "d"
          }
        },
        "y": {
          "field": "valor",
          "type": "quantitative",
          "title": "Compra + energia acumulada",
          "scale": {
            "zero": false
          },
          "axis": {
            "format": "$,.0f",
            "tickCount": 5
          }
        },
        "color": {
          "field": "Carro",
          "type": "nominal",
          "sort": {
            "field": "tipo",
            "op": "min"
          },
          "scale": {
            "range": [
              "#191919",
              "#E0B000"
            ]
          },
          "legend": {
            "orient": "top",
            "title": null,
            "direction": "horizontal"
          }
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum[''Custo acumulado combustão'']) || isValid(datum[''Custo acumulado elétrico''])"
        },
        {
          "calculate": "max(datum[''Ano de uso''] - 0.5, 0)",
          "as": "_x0"
        },
        {
          "calculate": "min(datum[''Ano de uso''] + 0.5, datum.amax)",
          "as": "_x1"
        }
      ],
      "mark": {
        "type": "rect",
        "color": "#191919",
        "opacity": 0.01
      },
      "encoding": {
        "x": {
          "field": "_x0",
          "type": "quantitative",
          "title": "Anos de uso"
        },
        "x2": {
          "field": "_x1"
        },
        "y": {
          "value": 0
        },
        "y2": {
          "value": {
            "expr": "height"
          }
        },
        "tooltip": [
          {
            "field": "Ano de uso",
            "title": "Ano de uso"
          },
          {
            "field": "tt_c",
            "title": "Combustão: compra + energia"
          },
          {
            "field": "tt_e",
            "title": "Elétrico: compra + energia"
          },
          {
            "field": "Saldo no ano"
          }
        ]
      }
    }
  ]
}'
